_BARE_SAFE = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._-+=/:\\")

def _quote(value):
    text = str(value)
    if text and all(c in _BARE_SAFE for c in text):
        return text
    return '"' + text.replace('"', '""') + '"'
